#include <stdint.h>
#include "stm32l476xx.h"

static void delay(volatile uint32_t count) {
	while (count--) {
	}
}

int main(void) {
	// 1. Enable GPIOA clock
	RCC->AHB2ENR |= RCC_AHB2ENR_GPIOAEN;

	// 2. PA5 -> output
	GPIOA->MODER &= ~GPIO_MODER_MODE5;
	GPIOA->MODER |= GPIO_MODER_MODE5_0;

	while (1) {
		// 3. Toggle PA5
		GPIOA->ODR ^= GPIO_ODR_OD5;
		delay(500000);
	}
}
